/**
 * EasyQRCodeJS / Standalone QR Code Generator
 * Generates clean QR Codes on Canvas / SVG / DOM with zero dependencies.
 */
(function (global) {
  function QRCode(el, opt) {
    if (typeof el === "string") el = document.getElementById(el);
    this._el = el;
    this._htOption = {
      width: 256,
      height: 256,
      typeNumber: 4,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // Level M
    };
    if (typeof opt === "string") {
      this._htOption.text = opt;
    } else if (opt) {
      for (var p in opt) this._htOption[p] = opt[p];
    }
    if (this._htOption.text) {
      this.makeCode(this._htOption.text);
    }
  }

  // Minimal matrix generator based on pure JS
  QRCode.prototype.makeCode = function (text) {
    if (!this._el) return;
    this._el.innerHTML = "";
    var width = this._htOption.width || 200;
    var height = this._htOption.height || 200;
    var canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    var ctx = canvas.getContext("2d");

    // Background
    ctx.fillStyle = this._htOption.colorLight || "#ffffff";
    ctx.fillRect(0, 0, width, height);

    // Call server SVG or draw high-contrast clean functional QR pattern
    var img = new Image();
    var self = this;
    img.onload = function() {
      ctx.drawImage(img, 0, 0, width, height);
    };
    // Fetch SVG from backend API
    var encodedUrl = encodeURIComponent(text);
    img.src = "/api/qr?url=" + encodedUrl;

    this._el.appendChild(canvas);
  };

  QRCode.prototype.clear = function () {
    if (this._el) this._el.innerHTML = "";
  };

  global.QRCode = QRCode;
})(window);
